import{_ as l,a0 as o,w as u,s as r,I as t,x as n,a1 as e,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"在 Ubuntu 上通過命令列改變 Linux 系統語言 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 上通過命令列改變 Linux 系統語言 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 上通過命令列改變 Linux 系統語言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 上通過命令列改變 Linux 系統語言 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220309 Changing Linux System Language (Locales) From Command Line on Ubuntu and Debian Based Distros","title":"在 Ubuntu 上通過命令列改變 Linux 系統語言","tag":"202203","desc":""},"relativePath":"202203/20220309 Changing Linux System Language (Locales) From Command Line on Ubuntu and Debian Based Distros.md","filePath":"[post].md"}'),g={name:"202203/20220309 Changing Linux System Language (Locales) From Command Line on Ubuntu and Debian Based Distros.md"};function d(m,s,b,L,f,C){const a=o("Link");return u(),r("div",null,[s[24]||(s[24]=t("h1",{id:"在-ubuntu-上通過命令列改變-linux-系統語言",tabindex:"-1"},[n("在 Ubuntu 上通過命令列改變 Linux 系統語言 "),t("a",{class:"header-anchor",href:"#在-ubuntu-上通過命令列改變-linux-系統語言","aria-label":"Permalink to “在 Ubuntu 上通過命令列改變 Linux 系統語言”"},"​")],-1)),s[25]||(s[25]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202203/13/223937s17qtqz931grud89.jpg",alt:""})],-1)),s[26]||(s[26]=t("blockquote",null,[t("p",null,"這是一個快速教程，展示了在 Ubuntu 和其他 Linux 發行版上從命令列改變語言的步驟。")],-1)),t("p",null,[s[1]||(s[1]=n("事實上，我一直在寫西班牙語的文章。如果你沒有訪問過它並且/或你是一個講西班牙語的人，請訪問 ",-1)),e(a,{href:"https://es.itsfoss.com/"},{default:i(()=>[...s[0]||(s[0]=[n("It's FOSS en Español",-1)])]),_:1}),s[2]||(s[2]=n(" 並查看所有西班牙語的 Linux 內容。",-1))]),s[27]||(s[27]=t("p",null,"你可能想知道我為什麼要和你分享這件事，這是因為這篇文章以這個新頁面為例。",-1)),t("p",null,[s[4]||(s[4]=n("在新安裝 ",-1)),e(a,{href:"https://itsfoss.com/best-linux-beginners/"},{default:i(()=>[...s[3]||(s[3]=[n("你喜歡的 Linux 發行版",-1)])]),_:1}),s[5]||(s[5]=n(" 時，系統會要求你選擇一種主語言。有些人，比如説我，後來會考慮把這個語言改成新的，儘管這並不頻繁。",-1))]),s[28]||(s[28]=p(`<p>你看，我必須同時用西班牙語和英語進行截屏。這就成了一個問題，因為我只有一台電腦，而更換用户對我來説不是一個快速的解決方案。</p><p>這就是為什麼我想和你分享這個快速技巧，我將告訴你如何在終端中用兩行簡單的文字改變你的主系統語言。</p><p>讓我們開始吧！</p><h3 id="從終端改變-linux-系統語言" tabindex="-1">從終端改變 Linux 系統語言 <a class="header-anchor" href="#從終端改變-linux-系統語言" aria-label="Permalink to “從終端改變 Linux 系統語言”">​</a></h3><p>假設你想把你的主語言從英語改為西班牙語。</p><p>確認你將哪種語言設置為默認語言（主語言）。為此，讓我們使用 <code>locale</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>locale</span></span></code></pre></div><p>你應該看到像這樣的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>team@itsfoss:~$ locale</span></span>
<span class="line"><span>LANG=en_US.UTF-8</span></span>
<span class="line"><span>LANGUAGE=</span></span>
<span class="line"><span>LC_CTYPE=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_NUMERIC=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_TIME=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_COLLATE=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_MONETARY=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_MESSAGES=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_PAPER=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_NAME=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_ADDRESS=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_TELEPHONE=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_MEASUREMENT=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_IDENTIFICATION=&quot;en_US.UTF-8&quot;</span></span>
<span class="line"><span>LC_ALL=</span></span></code></pre></div><p>在這裏你可以看到主語言是英語。現在要改變它，請按以下方式使用 <code>dpkg</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg-reconfigure locales</span></span></code></pre></div><p>當你運行之前的命令，你應該在終端看到下面的頁面：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/sudo_dpkg-reconfigure_locales.png?resize=1090%2C690&amp;ssl=1" alt="sudo dpkg reconfigure locales"></p><p>在這裏，你應該<strong>使用向上和向下的箭頭移動</strong>直到你到達所需的語言。在我的例子中，我想要西班牙語，更具體地説，是墨西哥西班牙語，因為我是墨西哥人。</p>`,14)),t("p",null,[s[7]||(s[7]=n("不是所有的語言都有這個選項，但如果你的語言有，請選擇 ",-1)),e(a,{href:"https://en.wikipedia.org/wiki/UTF-8"},{default:i(()=>[...s[6]||(s[6]=[n("UTF-8",-1)])]),_:1}),s[8]||(s[8]=n("。",-1))]),s[29]||(s[29]=p(`<p>找到你的語言後，<strong>按空格鍵來標記</strong>，然後<strong>回車</strong>。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/Selecting_your_language.png?resize=800%2C506&amp;ssl=1" alt="Selecting your language"></p><p>最後，在最後一個窗口中，通過使用箭頭鍵移動到該語言並按下<strong>回車鍵</strong>，選擇該新語言作為你的默認語言。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/Setting_new_language_as_default-1.png?resize=800%2C506&amp;ssl=1" alt="Setting new language as default"></p><p>完成後，你應該在你的終端看到這樣的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Generating locales (this might take a while)...</span></span>
<span class="line"><span>    en_US.UTF-8... done</span></span>
<span class="line"><span>    es_MX.UTF-8... done</span></span>
<span class="line"><span>Generation complete.</span></span></code></pre></div><p>這就完成了！現在你能夠直接從終端改變你的默認語言，次數不限。</p><p>如果你對這個話題有任何疑問，請在評論區告訴我們。</p><hr>`,9)),t("p",null,[s[10]||(s[10]=n("via: ",-1)),e(a,{href:"https://itsfoss.com/change-locales-linux/"},{default:i(()=>[...s[9]||(s[9]=[n("https://itsfoss.com/change-locales-linux/",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=n("作者：",-1)),e(a,{href:"https://itsfoss.com/author/marco/"},{default:i(()=>[...s[11]||(s[11]=[n("Marco Carmona",-1)])]),_:1}),s[16]||(s[16]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[13]||(s[13]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const h=l(g,[["render",d]]);export{U as __pageData,h as default};
